                if addrow and int(addrow['locked'] or 0):return self.redirect('/rations?id='+str(rid),'Kombine dengeleme uygulanmadı: artırılacak yem kilitli.')
                newkg=max(0.0,float(row['kg_per_head_day'] or 0)+rd)
