    if path == '/rations':
        return html.replace('</body>', DEV43_DESKTOP_RATION_CSS + '</body>')
    brand_only = DEV43_DESKTOP_RATION_CSS.split('<script id="dev43-desktop-ration-polish-script">')[0]
    return html.replace('</body>', brand_only + '</body>')



